source2='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 3 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(cells) >= 4:
                boxes.append((min(y for y, x in cells), max(y for y, x in cells),
                              min(x for y, x in cells), max(x for y, x in cells)))

    centers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                          for r0, r1, c0, c1 in boxes)]
    out = [row[:] for row in grid]
    patches = list(centers)
    halo = [(r, c) for r in range(h) for c in range(w)
            if grid[r][c] == 2 and (r, c) not in centers and
            any(max(abs(r-y), abs(c-x)) == 2 for y, x in centers)]
    patches.extend(halo)
    for r, c in patches:
        omit_top = any((r+1, c+2) == (y, x) for y, x in centers)
        for y in range(max(0, r-1 + int(omit_top)), min(h, r+2)):
            for x in range(max(0, c-1), min(w, c+2)):
                out[y][x] = 1
    for r, c in centers:
        out[r][c] = 2
    for r, c in halo:
        # A nearby halo can merge with a marker band at the object's edge.
        for r0, r1, c0, c1 in boxes:
            if r < r0 and c0 <= c <= c1:
                for x in range(w):
                    if grid[r][x] == 2 and x != c and c0 <= x <= c1 and not any(max(abs(r-y), abs(x-z)) == 2 for y, z in centers):
                        out[r][x] = 0
    return out
'''
